import { Component, OnInit, OnDestroy, HostListener } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { SoportesService } from '../services/soportes.service';
import { Soporte } from '../models/soporte.model';
import { User } from '../models/user.model';

declare const bootstrap: any;

type FiltroEstado = 'todos' | 'pendiente' | 'si' | 'no';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
})
export class DashboardComponent implements OnInit, OnDestroy {
  currentUser: User | null = null;
  soportes: Soporte[] = [];
  loading = false;
  error = '';
  successMsg = '';

  // Filtros
  filtroEstado: FiltroEstado = 'todos';
  searchTerm = '';

  // Nueva solicitud
  nuevaSolicitudForm!: FormGroup;
  savingNew = false;
  imagenPreview: string | null = null;
  nuevaModalVisible = false;

  // Ver imagen ampliada
  imagenViewer: string | null = null;

  // Seguimiento modal
  seguimientoForm!: FormGroup;
  selectedSoporte: Soporte | null = null;
  savingSeguimiento = false;

  // Cambiar contraseña
  cambioClaveForm!: FormGroup;
  savingClave = false;
  claveError = '';
  claveSuccess = '';

  // Export excel (admin)
  exportForm!: FormGroup;
  exporting = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private soportesService: SoportesService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.currentUser = this.authService.currentUser;

    this.nuevaSolicitudForm = this.fb.group({
      motivo: ['', [Validators.required, Validators.minLength(5)]],
    });

    this.seguimientoForm = this.fb.group({
      fechaRespuesta: [''],
      resolvio: [''],
      observaciones: [''],
    });

    this.cambioClaveForm = this.fb.group({
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required, Validators.minLength(6)]],
    });

    this.exportForm = this.fb.group({
      desde: ['', Validators.required],
      hasta: ['', Validators.required],
    });

    this.loadSoportes();
  }

  ngOnDestroy(): void {}

  // ─── Roles ───────────────────────────────────────────────────────────────────

  get isAdmin(): boolean  { return this.currentUser?.role === 'admin'; }
  get isSoporte(): boolean { return this.currentUser?.role === 'soporte'; }
  get isUser(): boolean   { return this.currentUser?.role === 'user'; }

  // ─── Permisos por fila ───────────────────────────────────────────────────────

  canSeguimiento(): boolean {
    return this.isAdmin || this.isSoporte;
  }

  canDelete(s: Soporte): boolean {
    if (this.isSoporte) return false;
    if (this.isAdmin) return true;
    // User: solo pendientes propias
    const tieneMovimiento = !!(s.fechaRespuesta || s.resolvio !== null && s.resolvio !== undefined);
    return !tieneMovimiento && s.usuario?.id === this.currentUser?.id;
  }

  // ─── Filtros ─────────────────────────────────────────────────────────────────

  get filteredSoportes(): Soporte[] {
    let result = [...this.soportes];

    if (this.filtroEstado === 'pendiente') {
      result = result.filter(s => s.resolvio === null || s.resolvio === undefined);
    } else if (this.filtroEstado === 'si') {
      result = result.filter(s => s.resolvio === true);
    } else if (this.filtroEstado === 'no') {
      result = result.filter(s => s.resolvio === false);
    }

    const term = this.searchTerm.trim().toLowerCase();
    if (term) {
      result = result.filter(s =>
        s.usuario?.area?.toLowerCase().includes(term) ||
        s.usuario?.nombre?.toLowerCase().includes(term)
      );
    }

    return result;
  }

  contarEstado(estado: FiltroEstado): number {
    if (estado === 'todos') return this.soportes.length;
    if (estado === 'pendiente') return this.soportes.filter(s => s.resolvio === null || s.resolvio === undefined).length;
    if (estado === 'si') return this.soportes.filter(s => s.resolvio === true).length;
    return this.soportes.filter(s => s.resolvio === false).length;
  }

  // ─── Carga de datos ──────────────────────────────────────────────────────────

  loadSoportes(): void {
    this.loading = true;
    this.soportesService.getAll().subscribe({
      next: (data) => { this.soportes = data; this.loading = false; },
      error: () => { this.error = 'Error al cargar los soportes'; this.loading = false; },
    });
  }

  // ─── Nueva solicitud ─────────────────────────────────────────────────────────

  openNuevaSolicitud(): void {
    this.nuevaSolicitudForm.reset();
    this.imagenPreview = null;
    this.nuevaModalVisible = true;
    const modal = new bootstrap.Modal(document.getElementById('nuevaSolicitudModal'));
    modal.show();
    document.getElementById('nuevaSolicitudModal')!.addEventListener('hidden.bs.modal', () => {
      this.nuevaModalVisible = false;
    }, { once: true });
  }

  guardarNuevaSolicitud(): void {
    if (this.nuevaSolicitudForm.invalid) { this.nuevaSolicitudForm.markAllAsTouched(); return; }
    this.savingNew = true;
    const { motivo } = this.nuevaSolicitudForm.value;
    this.soportesService.create(motivo, this.imagenPreview).subscribe({
      next: () => {
        this.savingNew = false;
        this.imagenPreview = null;
        this.nuevaModalVisible = false;
        bootstrap.Modal.getInstance(document.getElementById('nuevaSolicitudModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Solicitud creada exitosamente');
      },
      error: (err) => { this.savingNew = false; this.error = err?.error?.message || 'Error al crear la solicitud'; },
    });
  }

  // ─── Imagen (drag, drop, paste) ──────────────────────────────────────────────

  @HostListener('document:paste', ['$event'])
  onDocumentPaste(event: ClipboardEvent): void {
    if (!this.nuevaModalVisible) return;
    const items = event.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (file) { this.processImageFile(file); break; }
      }
    }
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    (event.currentTarget as HTMLElement).classList.add('drag-over');
  }

  onDragLeave(event: DragEvent): void {
    (event.currentTarget as HTMLElement).classList.remove('drag-over');
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    (event.currentTarget as HTMLElement).classList.remove('drag-over');
    const file = event.dataTransfer?.files[0];
    if (file && file.type.startsWith('image/')) this.processImageFile(file);
  }

  onFileInput(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (file) this.processImageFile(file);
  }

  private processImageFile(file: File): void {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_W = 1000;
        const scale = img.width > MAX_W ? MAX_W / img.width : 1;
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext('2d')!.drawImage(img, 0, 0, canvas.width, canvas.height);
        this.imagenPreview = canvas.toDataURL('image/jpeg', 0.78);
      };
      img.src = e.target!.result as string;
    };
    reader.readAsDataURL(file);
  }

  removeImagen(): void { this.imagenPreview = null; }

  openImagenViewer(imagen: string): void {
    this.imagenViewer = imagen;
    const modal = new bootstrap.Modal(document.getElementById('imagenViewerModal'));
    modal.show();
  }

  // ─── Seguimiento ─────────────────────────────────────────────────────────────

  openSeguimiento(soporte: Soporte): void {
    this.selectedSoporte = soporte;
    this.seguimientoForm.patchValue({
      fechaRespuesta: soporte.fechaRespuesta ? this.toDatetimeLocal(soporte.fechaRespuesta) : '',
      resolvio: soporte.resolvio === true ? 'true' : soporte.resolvio === false ? 'false' : '',
      observaciones: soporte.observaciones || '',
    });
    const modal = new bootstrap.Modal(document.getElementById('seguimientoModal'));
    modal.show();
  }

  guardarSeguimiento(): void {
    if (!this.selectedSoporte) return;
    this.savingSeguimiento = true;
    const val = this.seguimientoForm.value;
    const payload: any = { observaciones: val.observaciones || null };
    if (val.fechaRespuesta) payload.fechaRespuesta = new Date(val.fechaRespuesta).toISOString();
    if (val.resolvio !== '' && val.resolvio !== null) payload.resolvio = val.resolvio === 'true';

    this.soportesService.update(this.selectedSoporte.id, payload).subscribe({
      next: () => {
        this.savingSeguimiento = false;
        bootstrap.Modal.getInstance(document.getElementById('seguimientoModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Seguimiento guardado correctamente');
      },
      error: (err) => { this.savingSeguimiento = false; this.error = err?.error?.message || 'Error al guardar seguimiento'; },
    });
  }

  // ─── Eliminar ────────────────────────────────────────────────────────────────

  eliminarSoporte(soporte: Soporte): void {
    if (!confirm(`¿Eliminar la solicitud #${soporte.id}?`)) return;
    this.soportesService.delete(soporte.id).subscribe({
      next: () => { this.loadSoportes(); this.showSuccess('Solicitud eliminada'); },
      error: (err) => { this.error = err?.error?.message || 'Error al eliminar'; },
    });
  }

  // ─── Cambio de contraseña ────────────────────────────────────────────────────

  openCambioClave(): void {
    this.cambioClaveForm.reset();
    this.claveError = '';
    this.claveSuccess = '';
    const modal = new bootstrap.Modal(document.getElementById('cambioClaveModal'));
    modal.show();
  }

  guardarCambioClave(): void {
    if (this.cambioClaveForm.invalid) { this.cambioClaveForm.markAllAsTouched(); return; }
    const { password, confirmPassword } = this.cambioClaveForm.value;
    if (password !== confirmPassword) { this.claveError = 'Las contraseñas no coinciden'; return; }
    this.savingClave = true;
    this.claveError = '';
    this.authService.changePassword(password, confirmPassword).subscribe({
      next: () => { this.savingClave = false; this.claveSuccess = 'Contraseña cambiada exitosamente'; this.cambioClaveForm.reset(); },
      error: (err) => { this.savingClave = false; this.claveError = err?.error?.message || 'Error al cambiar la contraseña'; },
    });
  }

  // ─── Export Excel ────────────────────────────────────────────────────────────

  openExportModal(): void {
    this.exportForm.reset();
    const modal = new bootstrap.Modal(document.getElementById('exportModal'));
    modal.show();
  }

  exportarExcel(): void {
    if (this.exportForm.invalid) { this.exportForm.markAllAsTouched(); return; }
    this.exporting = true;
    const { desde, hasta } = this.exportForm.value;
    this.soportesService.exportExcel(desde, hasta).subscribe({
      next: (blob) => {
        this.exporting = false;
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `soportes_${desde}_${hasta}.xlsx`; a.click();
        window.URL.revokeObjectURL(url);
        bootstrap.Modal.getInstance(document.getElementById('exportModal'))?.hide();
      },
      error: () => { this.exporting = false; this.error = 'Error al exportar el archivo'; },
    });
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────────

  logout(): void { this.authService.logout(); }

  formatDate(dateStr: string | null | undefined): string {
    if (!dateStr) return '—';
    return new Date(dateStr).toLocaleString('es-CO', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  private toDatetimeLocal(dateStr: string): string {
    const d = new Date(dateStr);
    const p = (n: number) => n.toString().padStart(2, '0');
    return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
  }

  private showSuccess(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ''), 4000);
  }
}
<!-- ═══ NAVBAR ═══════════════════════════════════════════════════════════════ -->
<nav class="navbar navbar-expand-lg navbar-dark" style="background: #1e40af;">
  <div class="container-fluid px-4">
    <span class="navbar-brand">
      <i class="bi-chat-dots-fill me-2"></i>SysApolo — Soporte
    </span>
    <div class="d-flex align-items-center gap-2 ms-auto flex-wrap">
      <span class="text-white nav-user-info me-1">
        <i class="bi bi-person-circle me-1"></i>{{ currentUser?.nombre }}
        <span class="badge bg-light text-primary ms-1" *ngIf="isAdmin">Admin</span>
        <span class="badge bg-warning text-dark ms-1" *ngIf="isSoporte">Soporte</span>
      </span>

      <!-- Solo Admin -->
      <ng-container *ngIf="isAdmin">
        <button class="btn btn-outline-light btn-sm" routerLink="/users">
          <i class="bi bi-people me-1"></i>Usuarios
        </button>
        <button class="btn btn-outline-light btn-sm" (click)="openExportModal()">
          <i class="bi bi-file-earmark-excel me-1"></i>Excel
        </button>
      </ng-container>

      <!-- Admin y User: Nueva Solicitud -->
      <button *ngIf="!isSoporte" class="btn btn-light btn-sm" (click)="openNuevaSolicitud()">
        <i class="bi bi-plus-lg me-1"></i>Nueva Solicitud
      </button>

      <!-- Todos -->
      <button class="btn btn-outline-light btn-sm" (click)="openCambioClave()">
        <i class="bi bi-key me-1"></i>Cambiar Contraseña
      </button>
      <button class="btn btn-outline-light btn-sm" (click)="logout()">
        <i class="bi bi-box-arrow-right me-1"></i>Salir
      </button>
    </div>
  </div>
</nav>

<!-- ═══ CONTENIDO ════════════════════════════════════════════════════════════ -->
<div class="container-fluid px-4 py-4">

  <!-- Alertas -->
  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg=''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error=''"></button>
  </div>

  <div class="card">

    <!-- ── Filtros + Búsqueda ────────────────────────────────────────────── -->
    <div class="card-header">
      <div class="d-flex align-items-center justify-content-between flex-wrap gap-3">

        <!-- Radio buttons de estado -->
        <div class="d-flex align-items-center gap-2 flex-wrap">
          <span class="fw-semibold text-muted small me-1">Filtrar:</span>

          <div class="filtro-radio-group">
            <input type="radio" id="f-todos" name="filtro" [(ngModel)]="filtroEstado" value="todos" class="btn-check">
            <label for="f-todos" class="btn btn-sm filtro-btn filtro-todos">
              Todos <span class="filtro-count">{{ contarEstado('todos') }}</span>
            </label>

            <input type="radio" id="f-pendiente" name="filtro" [(ngModel)]="filtroEstado" value="pendiente" class="btn-check">
            <label for="f-pendiente" class="btn btn-sm filtro-btn filtro-pendiente">
              Pendiente <span class="filtro-count">{{ contarEstado('pendiente') }}</span>
            </label>

            <input type="radio" id="f-si" name="filtro" [(ngModel)]="filtroEstado" value="si" class="btn-check">
            <label for="f-si" class="btn btn-sm filtro-btn filtro-si">
              SI <span class="filtro-count">{{ contarEstado('si') }}</span>
            </label>

            <input type="radio" id="f-no" name="filtro" [(ngModel)]="filtroEstado" value="no" class="btn-check">
            <label for="f-no" class="btn btn-sm filtro-btn filtro-no">
              NO <span class="filtro-count">{{ contarEstado('no') }}</span>
            </label>
          </div>
        </div>

        <!-- Búsqueda (admin y soporte) -->
        <div class="d-flex align-items-center gap-2" *ngIf="isAdmin || isSoporte">
          <div class="input-group input-group-sm" style="width: 260px;">
            <span class="input-group-text bg-white">
              <i class="bi bi-search text-muted"></i>
            </span>
            <input
              type="text"
              class="form-control"
              placeholder="Buscar por área o usuario..."
              [(ngModel)]="searchTerm"
            />
            <span class="input-group-text">
              <span class="badge" [class.bg-primary]="isAdmin" [class.bg-warning]="isSoporte" [class.text-dark]="isSoporte">
                {{ isAdmin ? 'Admin' : 'Soporte' }}
              </span>
            </span>
          </div>
          <button *ngIf="searchTerm" class="btn btn-sm btn-outline-secondary" (click)="searchTerm=''">
            <i class="bi bi-x"></i>
          </button>
        </div>

      </div>
    </div>

    <!-- Loading -->
    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
      <p class="mt-2 text-muted">Cargando solicitudes...</p>
    </div>

    <!-- Empty state -->
    <div class="text-center py-5" *ngIf="!loading && filteredSoportes.length === 0">
      <i class="bi bi-inbox" style="font-size: 3rem; color:#94a3b8;"></i>
      <p class="mt-2 text-muted">
        {{ soportes.length === 0 ? 'No hay solicitudes de soporte' : 'No hay resultados para el filtro seleccionado' }}
      </p>
      <button *ngIf="!isSoporte && soportes.length === 0" class="btn btn-primary btn-sm" (click)="openNuevaSolicitud()">
        <i class="bi bi-plus-lg me-1"></i>Crear primera solicitud
      </button>
    </div>

    <!-- ── Tabla ──────────────────────────────────────────────────────────── -->
    <div class="table-responsive" *ngIf="!loading && filteredSoportes.length > 0">
      <table class="table table-hover mb-0">
        <thead>
          <tr>
            <th style="width:50px">#</th>
            <th style="width:140px">Fecha Solicitud</th>
            <th>Motivo / Descripción</th>
            <th style="width:50px" title="Imagen adjunta">IMG</th>
            <th *ngIf="isAdmin || isSoporte" style="width:120px">Área</th>
            <th *ngIf="isAdmin || isSoporte">Quien Realiza</th>
            <th *ngIf="isAdmin || isSoporte" style="width:110px">Teléfono</th>
            <th style="width:140px">Fecha Respuesta</th>
            <th style="width:90px">Resolvió</th>
            <th>Observaciones</th>
            <th class="text-center" style="width:100px">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let s of filteredSoportes">
            <td class="text-muted fw-bold">{{ s.id }}</td>
            <td class="small" style="white-space:nowrap">{{ formatDate(s.fechaSolicitud) }}</td>
            <td>
              <span class="motivo-text d-block" [title]="s.motivo">{{ s.motivo }}</span>
            </td>
            <td class="text-center">
              <button
                *ngIf="s.imagen"
                class="btn btn-sm btn-link p-0"
                title="Ver imagen adjunta"
                (click)="openImagenViewer(s.imagen!)"
              >
                <i class="bi bi-image text-primary" style="font-size:1.1rem"></i>
              </button>
              <span *ngIf="!s.imagen" class="text-muted small">—</span>
            </td>
            <td *ngIf="isAdmin || isSoporte" class="small">{{ s.usuario.area || '—' }}</td>
            <td *ngIf="isAdmin || isSoporte" class="small">{{ s.usuario.nombre }}</td>
            <td *ngIf="isAdmin || isSoporte" class="small">
              <a *ngIf="s.usuario.telefono" [href]="'tel:'+s.usuario.telefono" class="text-decoration-none">
                <i class="bi bi-telephone me-1 text-success"></i>{{ s.usuario.telefono }}
              </a>
              <span *ngIf="!s.usuario.telefono" class="text-muted">—</span>
            </td>
            <td class="small" style="white-space:nowrap">{{ formatDate(s.fechaRespuesta) }}</td>
            <td>
              <span *ngIf="s.resolvio === true"  class="badge-si">SI</span>
              <span *ngIf="s.resolvio === false" class="badge-no">NO</span>
              <span *ngIf="s.resolvio === null || s.resolvio === undefined" class="badge-pendiente">Pendiente</span>
            </td>
            <td>
              <span class="motivo-text d-block text-muted small" [title]="s.observaciones || ''">
                {{ s.observaciones || '—' }}
              </span>
            </td>
            <td class="text-center" style="white-space:nowrap">
              <!-- Seguimiento: admin y soporte -->
              <button
                *ngIf="canSeguimiento()"
                class="btn btn-outline-primary btn-sm me-1"
                title="Asignar Seguimiento"
                (click)="openSeguimiento(s)"
              >
                <i class="bi bi-pencil-square"></i>
              </button>
              <!-- Eliminar: admin siempre, user solo si pendiente y propio -->
              <button
                *ngIf="canDelete(s)"
                class="btn btn-outline-danger btn-sm"
                title="Eliminar"
                (click)="eliminarSoporte(s)"
              >
                <i class="bi bi-trash"></i>
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

  </div><!-- /card -->
</div>

<!-- ═══ MODAL: Nueva Solicitud ═══════════════════════════════════════════════ -->
<div class="modal fade" id="nuevaSolicitudModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-plus-circle me-2"></i>Nueva Solicitud de Soporte</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="nuevaSolicitudForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">
              Motivo / Descripción <span class="text-danger">*</span>
            </label>
            <textarea
              class="form-control"
              formControlName="motivo"
              rows="4"
              placeholder="Describa detalladamente el motivo de la solicitud..."
            ></textarea>
            <div class="text-danger small mt-1"
              *ngIf="nuevaSolicitudForm.get('motivo')?.touched && nuevaSolicitudForm.get('motivo')?.invalid">
              El motivo es requerido (mínimo 5 caracteres)
            </div>
          </div>

          <!-- Zona de imagen -->
          <div class="mb-2">
            <label class="form-label fw-semibold">
              <i class="bi bi-image me-1"></i>Imagen adjunta (pantallazo)
              <span class="text-muted fw-normal small ms-1">— opcional</span>
            </label>

            <!-- Preview -->
            <div *ngIf="imagenPreview" class="mb-2 position-relative d-inline-block">
              <img [src]="imagenPreview" class="img-thumbnail" style="max-height:220px; max-width:100%;" />
              <button type="button" class="btn btn-danger btn-sm position-absolute top-0 end-0 m-1"
                (click)="removeImagen()" title="Quitar imagen">
                <i class="bi bi-x-lg"></i>
              </button>
            </div>

            <!-- Drop zone -->
            <div
              *ngIf="!imagenPreview"
              class="drop-zone"
              (dragover)="onDragOver($event)"
              (dragleave)="onDragLeave($event)"
              (drop)="onDrop($event)"
            >
              <i class="bi bi-cloud-arrow-up drop-zone-icon"></i>
              <p class="mb-1 fw-semibold">Arrastra una imagen aquí</p>
              <p class="text-muted small mb-2">o pega con <kbd>Ctrl+V</kbd> en cualquier lugar del modal</p>
              <label class="btn btn-outline-primary btn-sm">
                <i class="bi bi-folder2-open me-1"></i>Seleccionar archivo
                <input type="file" accept="image/*" class="d-none" (change)="onFileInput($event)">
              </label>
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarNuevaSolicitud()" [disabled]="savingNew">
          <span *ngIf="savingNew" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-save me-1" *ngIf="!savingNew"></i>
          {{ savingNew ? 'Guardando...' : 'Grabar Solicitud' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Ver imagen ════════════════════════════════════════════════════ -->
<div class="modal fade" id="imagenViewerModal" tabindex="-1">
  <div class="modal-dialog modal-xl modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header py-2">
        <h6 class="modal-title"><i class="bi bi-image me-2"></i>Imagen adjunta</h6>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body text-center p-2">
        <img *ngIf="imagenViewer" [src]="imagenViewer" class="img-fluid rounded" style="max-height:80vh;" />
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Seguimiento ═══════════════════════════════════════════════════ -->
<div class="modal fade" id="seguimientoModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-clipboard2-check me-2"></i>Asignar Seguimiento
          <small *ngIf="selectedSoporte" class="ms-1 opacity-75">#{{ selectedSoporte.id }}</small>
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div *ngIf="selectedSoporte" class="mb-3">
          <label class="form-label fw-semibold text-muted small">Motivo de la solicitud</label>
          <p class="border rounded p-2 bg-light mb-0 small">{{ selectedSoporte.motivo }}</p>
        </div>
        <form [formGroup]="seguimientoForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha de Respuesta</label>
            <input type="datetime-local" class="form-control" formControlName="fechaRespuesta" />
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">¿Resolvió el problema?</label>
            <select class="form-select" formControlName="resolvio">
              <option value="">— Seleccione —</option>
              <option value="true">SI</option>
              <option value="false">NO</option>
            </select>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Observaciones</label>
            <textarea class="form-control" formControlName="observaciones" rows="4"
              placeholder="Ingrese las observaciones del seguimiento..."></textarea>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarSeguimiento()" [disabled]="savingSeguimiento">
          <span *ngIf="savingSeguimiento" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-check-lg me-1" *ngIf="!savingSeguimiento"></i>
          {{ savingSeguimiento ? 'Guardando...' : 'Guardar Seguimiento' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Cambio de Contraseña ══════════════════════════════════════════ -->
<div class="modal fade" id="cambioClaveModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-key me-2"></i>Cambiar Contraseña</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="alert alert-danger py-2 small" *ngIf="claveError">
          <i class="bi bi-exclamation-circle me-1"></i>{{ claveError }}
        </div>
        <div class="alert alert-success py-2 small" *ngIf="claveSuccess">
          <i class="bi bi-check-circle me-1"></i>{{ claveSuccess }}
        </div>
        <form [formGroup]="cambioClaveForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Nueva Contraseña</label>
            <input type="password" class="form-control" formControlName="password" placeholder="Mínimo 6 caracteres" />
            <div class="text-danger small mt-1"
              *ngIf="cambioClaveForm.get('password')?.touched && cambioClaveForm.get('password')?.invalid">
              Mínimo 6 caracteres
            </div>
          </div>
          <div class="mb-2">
            <label class="form-label fw-semibold">Repetir Contraseña</label>
            <input type="password" class="form-control" formControlName="confirmPassword" placeholder="Repita la contraseña" />
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary btn-sm" (click)="guardarCambioClave()" [disabled]="savingClave">
          <span *ngIf="savingClave" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingClave ? 'Guardando...' : 'Cambiar' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Exportar Excel ════════════════════════════════════════════════ -->
<div class="modal fade" id="exportModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-file-earmark-excel me-2"></i>Exportar a Excel</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="exportForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha Desde</label>
            <input type="date" class="form-control" formControlName="desde" />
            <div class="text-danger small mt-1"
              *ngIf="exportForm.get('desde')?.touched && exportForm.get('desde')?.invalid">Requerido</div>
          </div>
          <div class="mb-2">
            <label class="form-label fw-semibold">Fecha Hasta</label>
            <input type="date" class="form-control" formControlName="hasta" />
            <div class="text-danger small mt-1"
              *ngIf="exportForm.get('hasta')?.touched && exportForm.get('hasta')?.invalid">Requerido</div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-success btn-sm" (click)="exportarExcel()" [disabled]="exporting">
          <span *ngIf="exporting" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-download me-1" *ngIf="!exporting"></i>
          {{ exporting ? 'Exportando...' : 'Descargar' }}
        </button>
      </div>
    </div>
  </div>
</div>
